#!/usr/bin/env bash
# SCRIPT_JDOC: {"summary":"Screen ZC1 batch thread counts 10, 12, 14 and 16 on the frozen sustained fixture","kind":"mixed","weight":"heavy","role":"entrypoint"}
set -euo pipefail
root=$(cd "$(dirname "$0")/../../.." && pwd)
campaign="$root/benchmarks/intel-1340p/gemma-zc-speed-20260916"
out="$campaign/batch-thread-sweep"
build="$root/runtime/deployments/gemma-generation-parity-ddb93ad19-7871f502"
runtime="$root/runtime/gemma-vulkan-f32-0bdd7cd8b/runtime"
model="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B_q4_0-it.gguf"
draft="$root/../models/gemma-4-e4b-qat-mtp/gemma-4-E4B-it-qat-assistant-MTP-Q8_0.gguf"
fixture="$campaign/baseline/sustained-chat-512.json"
production=llama-gemma-zero-copy.service
mkdir -p "$out/runs"
export XDG_RUNTIME_DIR=/run/user/$(id -u);export DBUS_SESSION_BUS_ADDRESS=unix:path=$XDG_RUNTIME_DIR/bus
restore() { local rc=$?;for u in $(systemctl --user list-units --all --plain --no-legend 'gemma-zc-batchthreads-*.service' 2>/dev/null|awk '{print $1}');do systemctl --user stop "$u">/dev/null 2>&1||true;systemctl --user reset-failed "$u">/dev/null 2>&1||true;done;systemctl --user start "$production">/dev/null 2>&1||true;local ok=0;for _ in $(seq 1 180);do if curl -fsS http://127.0.0.1:18094/health>"$out/restored-health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;systemctl --user show "$production" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemorySwapCurrent -p MemorySwapPeak>"$out/restored-service.txt" 2>&1||true;[[ $ok == 1 ]]||rc=1;exit "$rc";};trap restore EXIT INT TERM
systemctl --user is-active --quiet "$production";[[ $(systemctl --user show whisper-stt.service -p ActiveState --value) == inactive ]];[[ $(systemctl --user show whisper-stt-diarizer.service -p ActiveState --value) == inactive ]];! pgrep -x diar-server>/dev/null;! pgrep -x whisper-cli>/dev/null;[[ $(awk '/MemAvailable:/{print $2}' /proc/meminfo) -ge 12582912 ]];systemctl --user stop "$production"
printf 'sequence\tthreads_batch\tdecode_tps\twall_s\tprefill_s\tdrafted\taccepted\tgenerated\tcontent_sha256\tmemory_peak\tswap_peak\ttemp_before_c\ttemp_after_c\n'>"$out/results.tsv"
run_one() { local seq=$1 threads=$2;local port=$((19300+seq));local unit="gemma-zc-batchthreads-${seq}.service";local dir="$out/runs/$(printf '%02d-t%d' "$seq" "$threads")";mkdir -p "$dir";local tb ta;tb=$(sensors -j|jq '[..|objects|to_entries[]?|select(.key|test("temp[0-9]+_input"))|.value]|max');systemd-run --user --unit "$unit" --collect -p Type=simple -p TimeoutStopSec=30 -p MemoryMax=16G -p MemorySwapMax=0 -p TasksMax=256 --setenv=LD_LIBRARY_PATH="$build/bin:$runtime" --setenv=GGML_VK_VISIBLE_DEVICES=0 --setenv=GGML_VK_EXPERIMENTAL_ATTN_MODE=f32 "$build/bin/llama-gemma-zero-copy-server" --model "$model" --draft "$draft" --alias gemma-4-e4b-qat-mtp-zero-copy --host 127.0.0.1 --port "$port" --ctx-size 32768 --batch-size 256 --ubatch-size 256 --threads 8 --threads-batch "$threads" --draft-max 3 --draft-min 1 --threadpools 0 --model-sampling 1 --max-output 2048 >"$dir/systemd-run.txt";local ok=0;for _ in $(seq 1 180);do if curl -fsS "http://127.0.0.1:$port/health">"$dir/health.json" 2>/dev/null;then ok=1;break;fi;sleep 1;done;[[ $ok == 1 ]];curl --max-time 180 -fsS "http://127.0.0.1:$port/v1/chat/completions" -H 'Content-Type: application/json' -H "X-Conversation-Id: batchthreads-$seq" --data-binary @"$fixture">"$dir/response.json";jq -e '.usage.completion_tokens==512 and .zero_copy.drafted==385 and .zero_copy.accepted==382 and .zero_copy.shared_bytes>0 and .zero_copy.copied_bytes==0' "$dir/response.json";jq -r '.choices[0].message.content' "$dir/response.json"|sha256sum|cut -d' ' -f1>"$dir/content-sha256.txt";systemctl --user show "$unit" -p ActiveState -p SubState -p MainPID -p NRestarts -p MemoryPeak -p MemorySwapPeak>"$dir/service.txt";local swap=$(sed -n 's/^MemorySwapPeak=//p' "$dir/service.txt");[[ $swap == 0 ]];local mem=$(sed -n 's/^MemoryPeak=//p' "$dir/service.txt");ta=$(sensors -j|jq '[..|objects|to_entries[]?|select(.key|test("temp[0-9]+_input"))|.value]|max');local dec=$(jq -r '.zero_copy.decode_tps' "$dir/response.json");local wall=$(jq -r '.zero_copy.wall_s' "$dir/response.json");local pre=$(jq -r '.zero_copy.prefill_s' "$dir/response.json");local drafted=$(jq -r '.zero_copy.drafted' "$dir/response.json");local accepted=$(jq -r '.zero_copy.accepted' "$dir/response.json");local gen=$(jq -r '.zero_copy.generated_tokens' "$dir/response.json");local hash=$(cat "$dir/content-sha256.txt");printf '%d\t%d\t%.9f\t%.9f\t%.9f\t%d\t%d\t%d\t%s\t%s\t%s\t%s\t%s\n' "$seq" "$threads" "$dec" "$wall" "$pre" "$drafted" "$accepted" "$gen" "$hash" "$mem" "$swap" "$tb" "$ta">>"$out/results.tsv";journalctl --user -u "$unit" --no-pager>"$dir/journal.txt";systemctl --user stop "$unit";systemctl --user reset-failed "$unit">/dev/null 2>&1||true;sleep 2;}
# Latin-square order, two observations per setting.
run_one 1 16;run_one 2 12;run_one 3 10;run_one 4 14;run_one 5 14;run_one 6 10;run_one 7 12;run_one 8 16
[[ $(awk -F '\t' 'NR>1{print $9}' "$out/results.tsv"|sort -u|wc -l) == 1 ]]
sha256sum "$out/results.tsv">"$out/SHA256SUMS"
